import{_ as a,c as t,a2 as o,o as s}from"./chunks/framework.BQmytedh.js";const h=JSON.parse('{"title":"杂项","description":"","frontmatter":{},"headers":[],"relativePath":"护肤/杂项.md","filePath":"护肤/杂项.md","lastUpdated":1734369888000}'),r={name:"护肤/杂项.md"};function f(n,e,l,i,c,p){return s(),t("div",null,e[0]||(e[0]=[o('<h1 id="杂项" tabindex="-1">杂项 <a class="header-anchor" href="#杂项" aria-label="Permalink to &quot;杂项&quot;">​</a></h1><ul><li><p>沐浴时间10分钟是最合适的，沐浴时间太长没有什么作用不说，还可能引起水合性皮炎，造成皮肤屏障受损，皮肤敏感。<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p></li><li><p>洗脸、洗手、洗澡后3分钟内是保湿的黄金时间，这时候涂保湿产品，久了之后皮肤会更细腻光滑。<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1:1]</a></sup></p></li><li><p>手肘、膝盖、脚后跟都是皮脂腺较少的部位，擦保湿霜的时候可别忘了它们，最好用点含尿素或者乳酸的保湿剂。<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1:2]</a></sup></p></li></ul><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p><a href="https://www.zhihu.com/question/428147299/answer/1755126413" target="_blank" rel="noreferrer">护肤最重要的是什么？ - 瑞颜医生的回答 - 知乎</a> <a href="#fnref1" class="footnote-backref">↩︎</a> <a href="#fnref1:1" class="footnote-backref">↩︎</a> <a href="#fnref1:2" class="footnote-backref">↩︎</a></p></li></ol></section>',4)]))}const u=a(r,[["render",f]]);export{h as __pageData,u as default};
